def choose_move(observation):
    def is_num(x):
        return isinstance(x, (int, float)) and not isinstance(x, bool)

    def is_pos(v):
        return (
            isinstance(v, (list, tuple))
            and len(v) >= 2
            and is_num(v[0])
            and is_num(v[1])
        )

    def as_pos(v):
        if is_pos(v):
            return (v[0], v[1])
        return None

    def key_match(key, needles):
        if not isinstance(key, str):
            return False
        k = key.lower()
        for n in needles:
            if n in k:
                return True
        return False

    def recurse_collect(obj, needles, out):
        if isinstance(obj, dict):
            for k, v in obj.items():
                if key_match(k, needles):
                    p = as_pos(v)
                    if p is not None:
                        out.append(p)
                recurse_collect(v, needles, out)
        elif isinstance(obj, (list, tuple)):
            for x in obj:
                recurse_collect(x, needles, out)

    def get_self_pos(obs):
        for needles in (("self", "me", "agent"), ("position", "pos")):
            found = []
            recurse_collect(obs, needles, found)
            if found:
                return found[0]
        return None

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def nearest(src, pts):
        best = None
        best_d = None
        for p in pts:
            d = manhattan(src, p)
            if best is None or d < best_d:
                best = p
                best_d = d
        return best, best_d

    def clamp_step(d):
        if d > 0:
            return 1
        if d < 0:
            return -1
        return 0

    pos = get_self_pos(observation)
    if pos is None:
        return [0, 0]

