    recurse_collect(observation, ("resource", "food", "coin", "treasure", "item", "pickup", "pickupable"), resources)

    enemies = []
    recurse_collect(observation, ("enemy", "opponent", "foe", "pursuer", "hunter", "chaser"), enemies)

    territories = []
    recurse_collect(observation, ("territory", "capture", "objective", "goal", "base", "flag"), territories)

    # Flee if a hostile is very close.
    if enemies:
        enemy, dist = nearest(pos, enemies)
        if dist is not None and dist <= 2:
            dx = clamp_step(pos[0] - enemy[0])
            dy = clamp_step(pos[1] - enemy[1])
            if dx == 0 and dy == 0:
                dx = 1
            return [dx, dy]

    # Prefer resources, then territory/objectives, then move toward center.
    for targets in (resources, territories, enemies):
        if targets:
            target, _ = nearest(pos, targets)
            dx = clamp_step(target[0] - pos[0])
            dy = clamp_step(target[1] - pos[1])
            if dx == 0 and dy == 0:
                return [0, 0]
            return [dx, dy]

    grid = observation.get("grid")
    if isinstance(grid, (list, tuple)) and grid and isinstance(grid[0], (list, tuple)):
        h = len(grid)
        w = len(grid[0]) if h else 0
        if h and w:
